CREATE TABLE IF NOT EXISTS cms_ai_policies(site_id BIGINT PRIMARY KEY REFERENCES cms_sites(id) ON DELETE CASCADE,connector_key VARCHAR(190) NOT NULL DEFAULT 'vazin-ai',model_key VARCHAR(190) NOT NULL DEFAULT '',monthly_request_limit INTEGER NOT NULL DEFAULT 1000,allow_drafting BOOLEAN NOT NULL DEFAULT TRUE,allow_translation BOOLEAN NOT NULL DEFAULT TRUE,allow_semantic_search BOOLEAN NOT NULL DEFAULT TRUE,require_human_review BOOLEAN NOT NULL DEFAULT TRUE,settings_json TEXT NOT NULL DEFAULT '{}',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_ai_prompt_templates(id BIGSERIAL PRIMARY KEY,site_id BIGINT REFERENCES cms_sites(id) ON DELETE CASCADE,template_key VARCHAR(190) NOT NULL,label TEXT NOT NULL,purpose VARCHAR(80) NOT NULL,prompt_text TEXT NOT NULL,is_system BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(site_id,template_key));
CREATE TABLE IF NOT EXISTS cms_ai_requests(id BIGSERIAL PRIMARY KEY,site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,page_id BIGINT REFERENCES cms_pages(id) ON DELETE SET NULL,request_key VARCHAR(190) NOT NULL UNIQUE,purpose VARCHAR(80) NOT NULL,model_key VARCHAR(190) NOT NULL DEFAULT '',input_hash VARCHAR(64) NOT NULL,output_json TEXT NOT NULL DEFAULT '{}',status VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','completed','failed','review_required','approved','rejected')),usage_json TEXT NOT NULL DEFAULT '{}',error_message TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_cms_ai_requests_site ON cms_ai_requests(site_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS cms_ai_reviews(id BIGSERIAL PRIMARY KEY,request_id BIGINT NOT NULL REFERENCES cms_ai_requests(id) ON DELETE CASCADE,reviewer_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,decision VARCHAR(20) NOT NULL CHECK(decision IN('approved','rejected')),note TEXT NOT NULL DEFAULT '',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_semantic_documents(id BIGSERIAL PRIMARY KEY,site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT NOT NULL,locale VARCHAR(10) NOT NULL DEFAULT 'en',content_hash VARCHAR(64) NOT NULL,embedding_json TEXT NOT NULL DEFAULT '[]',metadata_json TEXT NOT NULL DEFAULT '{}',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(site_id,entity_type,entity_id,locale));
INSERT INTO schema_migrations(version) VALUES('10.24.0') ON CONFLICT(version) DO NOTHING;